"""Extend the CPU controller with certified epoch planning.

Wire validation, allocation and both certificates are implemented here on top
of the supplied classifier, probability-compiler and metric primitives.
"""
import sys
sys.path.insert(0, '/workspace/vendor')

from fractions import Fraction

from validate import validate_request, Invalid
import metrics
import probability
import testcnnonnx
import testrnnonnx
from planner import Epoch


def _ceil_ratio(ratio, target):
    """ceil(ratio * target) with exact integer arithmetic."""
    numerator = ratio.numerator * target
    denominator = ratio.denominator
    return -((-numerator) // denominator)


def _jsonify_report(report):
    out = {}
    for level, block in report.items():
        out[level] = {
            'confusion': [[int(value) for value in row] for row in block['confusion']],
            'accuracy': float(block['accuracy']),
            'macro_precision': float(block['macro_precision']),
            'macro_recall': float(block['macro_recall']),
            'macro_f1': float(block['macro_f1']),
        }
    return out


def _predict(model, features):
    if not features:
        return []
    labels = [0] * len(features)
    if model == 'cnn':
        return testcnnonnx.evaluate_model_single_pass(features, labels)
    return testrnnonnx.evaluate_model_single_pass(features, labels)


def _ratio_of(counts, targets):
    ratio = Fraction(1)
    for count, target in zip(counts, targets):
        value = Fraction(count, target)
        if value < ratio:
            ratio = value
    return ratio


def solve_case(case):
    windows = case['windows']
    predictions = _predict(case['model'], [window[7] for window in windows])
    thresholds = probability.window_thresholds(case['stats'], windows)
    epoch = Epoch(case, predictions, thresholds)

    candidates = set()
    for target in epoch.targets:
        for k in range(target + 1):
            candidates.add(Fraction(k, target))
    candidates = sorted(candidates)
    bound = epoch.coverage_bound()
    upper = len(candidates) - 1
    while upper > 0 and candidates[upper] > bound:
        upper -= 1

    low = 0
    while low < upper:
        mid = (low + upper + 1) >> 1
        feasible, _ = epoch.feasible([_ceil_ratio(candidates[mid], t)
                                      for t in epoch.targets])
        if feasible:
            low = mid
        else:
            upper = mid - 1

    ratio = candidates[low]
    lower = [_ceil_ratio(ratio, target) for target in epoch.targets]
    solution = epoch.solve(lower)

    counts = solution['counts']
    achieved = _ratio_of(counts, epoch.targets)
    if achieved != ratio:
        raise RuntimeError('coverage mismatch')
    cut = None
    if ratio < 1:
        nxt = candidates[low + 1]
        feasible, cut = epoch.feasible([_ceil_ratio(nxt, target)
                                        for target in epoch.targets])
        if feasible:
            raise RuntimeError('maximal coverage not proved')

    report = metrics.selected_report(case['flows'], windows, predictions,
                                     solution['assignment'])
    return {
        'predictions': [int(value) for value in predictions],
        'reports': _jsonify_report(report),
        'ratio': [achieved.numerator, achieved.denominator],
        'thresholds': [int(value) for value in thresholds],
        'assignment': [int(value) for value in solution['assignment']],
        'utility': int(solution['utility']),
        'age': int(solution['age']),
        'flow': [int(value) for value in solution['flows']],
        'potential': [int(value) for value in solution['potentials']],
        'cut': cut,
    }


def run(raw):
    try:
        request = validate_request(raw)
    except Invalid:
        return {'error': 'invalid'}
    results = [solve_case(case) for case in request['cases']]
    return {'version': 3, 'results': results}
